const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const desk=document.createElement('section');desk.id='desk';desk.className='desk';desk.innerHTML=`<div class="connection"><div><span class="connection-icon">✉</span><strong>Почта не подключена</strong><span>Работайте с примерами или вставьте текст письма</span></div><button class="button" id="connection-info">Как подключить</button></div><div class="desk-layout"><section class="panel inbox"><div class="panel-title"><div><div class="eyebrow">ВХОДЯЩИЕ → ДЕЙСТВИЕ</div><h2>Рабочая очередь</h2></div><span class="tag">3 примера</span></div><div id="mail-list"></div><button class="button paste-button" id="paste-mail">+ Вставить своё письмо</button></section><section class="panel mail-view"><div id="mail-content"></div></section></div><section class="panel drafts"><div class="panel-title"><div><h2>Подготовленные черновики <span class="counter" id="draft-count">0</span></h2><p>Только в текущей вкладке. Скачайте результат до обновления страницы.</p></div></div><div id="draft-list" class="draft-list"><div class="draft-empty">Выберите письмо и подготовьте счёт, заявку или ответ.</div></div></section></div>`;
document.querySelector('.toolbar').before(desk);document.querySelector('h1').innerHTML='От письма — к результату<span>.</span>';document.querySelector('.heading p').textContent='Входящие, документы и тендеры в одном рабочем пространстве.';
const nav=document.querySelector('nav');nav.insertAdjacentHTML('afterbegin','<a href="#desk">✉ <span>Письма и документы</span></a>');document.querySelector('.breadcrumb b').textContent='Рабочий стол руководителя';
const mails=[{from:'Закупки · АО «Региональные сети»',subject:'Запрос счёта на оборудование',time:'09:42',kind:'Счёт',body:'Добрый день! Просим подготовить счёт на поставку 12 сетевых коммутаторов. Укажите срок поставки и условия оплаты. Реквизиты и согласованную цену направим отдельным письмом.',task:'Запросить реквизиты и цену, затем подготовить счёт.',customer:'АО «Региональные сети»',item:'Сетевой коммутатор',qty:12},{from:'Тендерный отдел · ГБУ «Мосинфосистемы»',subject:'Комплект документов для участия',time:'09:18',kind:'Заявка',body:'Просим подготовить заявку на поставку серверного оборудования. Нужны сведения об участнике и техническое предложение. Срок подачи — 17 сентября 2026, 18:00 МСК. Требования необходимо сверить с документацией закупки.',task:'Собрать сведения об участнике и техническое предложение.',customer:'ГБУ «Мосинфосистемы»',item:'Поставка серверного оборудования',qty:1},{from:'Договорной отдел · ПАО «Энергокомплекс»',subject:'Уточнение реквизитов организации',time:'Вчера',kind:'Ответ',body:'Для подготовки договора просим прислать полное наименование организации, ИНН, КПП, юридический адрес и банковские реквизиты. Пожалуйста, проверьте актуальность сведений.',task:'Подготовить ответ с актуальными реквизитами организации.',customer:'ПАО «Энергокомплекс»',item:'',qty:1}];let selectedMail=0;const drafts=[];
function renderMail(){document.querySelector('#mail-list').innerHTML=mails.map((m,i)=>`<button class="mail-item ${i===selectedMail?'chosen':''}" data-mail="${i}"><div class="mail-meta"><span>${i<3?'ПРИМЕР ПИСЬМА':'ВСТАВЛЕНО ВРУЧНУЮ'}</span><span>${esc(m.time)}</span></div><strong>${esc(m.subject)}</strong><p>${esc(m.from)}</p><span class="status">${esc(m.kind)}</span></button>`).join('');const m=mails[selectedMail];document.querySelector('#mail-content').innerHTML=`<div class="mail-head"><span class="tag">${selectedMail<3?'Демонстрационное письмо':'Текст добавлен вручную'}</span><h2>${esc(m.subject)}</h2><p>${esc(m.from)}</p></div><div class="mail-body">${esc(m.body)}</div><div class="next-step"><span>СЛЕДУЮЩИЙ ШАГ</span><p>${esc(m.task)}</p></div><div class="mail-actions"><button class="button primary" data-compose="${m.kind}">Подготовить ${m.kind==='Счёт'?'счёт':m.kind==='Заявка'?'заявку':'ответ'} ↗</button><button class="button" data-compose="${m.kind==='Ответ'?'Счёт':'Ответ'}">${m.kind==='Ответ'?'Создать счёт':'Написать ответ'}</button></div><p class="mail-disclaimer">Черновики формируются по шаблону. Отправка писем и подача на площадку не подключены.</p>`;}
const compose=document.createElement('dialog');compose.id='compose';document.body.append(compose);const cash=n=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);function field(label,name,value='',extra=''){return `<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function openCompose(type,editIndex=-1){const existing=editIndex>=0?drafts[editIndex]:null;const m=mails[selectedMail];compose.innerHTML=`<button class="close" type="button" data-close-compose aria-label="Закрыть">×</button><span class="tag">ЧЕРНОВИК · ${esc(type)}</span><h2>${type==='Счёт'?'Подготовить счёт':type==='Заявка'?'Подготовить заявку':'Подготовить ответ'}</h2><p>Заполните сведения и проверьте текст перед использованием.</p><form id="compose-form"><input type="hidden" name="type" value="${esc(type)}"><div class="form-grid">${field('Ваша организация','seller','','required')}${field('Заказчик / получатель','buyer',m.customer,'required')}${field('Номер документа','number','','required')}${field('Дата документа','date',new Date().toISOString().slice(0,10),'type="date" required')}</div>${type==='Счёт'?`<div class="form-grid">${field('Наименование товара / услуги','item',m.item,'required')}${field('Количество','qty',m.qty,'type="number" min="0.001" step="0.001" required')}${field('Цена за единицу без НДС, ₽','price','','type="number" min="0.01" step="0.01" required')}${field('НДС, % · 0 при отсутствии','vat',0,'type="number" min="0" max="100" step="0.01" required')}</div><label>Реквизиты поставщика и плательщика<textarea name="details" rows="4" placeholder="ИНН, КПП, адрес, банк, БИК и расчётный счёт" required></textarea></label><div class="invoice-total" id="invoice-total">Итого: заполните цену</div>`:`<label>${type==='Заявка'?'Текст заявки':'Текст ответа'}<textarea name="body" rows="8" required>${esc(type==='Заявка'?`Просим рассмотреть нашу заявку на участие в закупке «${m.item}».\n\nСведения об участнике: [заполнить]\nПредлагаемые товары / услуги: [заполнить]\nЦена и условия: [заполнить]\nПриложения по документации закупки: [перечислить]`:'Добрый день!\n\nВ ответ на ваше письмо сообщаем:\n[добавьте сведения или уточняющие вопросы]\n\nС уважением,\n[имя и должность]')}</textarea></label>`}<label>Примечания / условия<textarea name="notes" rows="2" placeholder="Срок поставки, условия оплаты или список приложений"></textarea></label><div class="form-notice">${type==='Заявка'?'Это шаблон сопроводительной заявки. Состав комплекта нужно сверить с документацией закупки.':'Заполненные данные не проверяются по внешним реестрам.'}</div><button class="button primary" type="submit">Добавить в черновики</button></form>`;compose.showModal();const f=document.querySelector('#compose-form');if(existing){for(const [key,value] of Object.entries(existing)){const input=f.elements.namedItem(key);if(input)input.value=value;}f.querySelector('[type=submit]').textContent='Сохранить изменения';}if(type==='Счёт')f.addEventListener('input',()=>{const a=new FormData(f),base=Number(a.get('qty'))*Number(a.get('price')),tax=base*Number(a.get('vat'))/100;document.querySelector('#invoice-total').textContent=`Без НДС: ${cash(base)} ₽ · НДС: ${cash(tax)} ₽ · Итого: ${cash(base+tax)} ₽`;});if(existing&&type==='Счёт')f.dispatchEvent(new Event('input'));f.addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(f));const updated={...existing,...values,source:existing?.source??m.subject,checks:existing?.checks??[]};if(editIndex>=0)drafts[editIndex]=updated;else drafts.push(updated);renderDrafts();compose.close();document.querySelector('#draft-list').scrollIntoView({behavior:'smooth',block:'center'});});}
function renderDrafts(){document.querySelector('#draft-count').textContent=drafts.length;document.querySelector('#draft-list').innerHTML=drafts.map((d,i)=>`<div class="draft-row"><span class="doc-icon">▤</span><div><strong>${esc(d.type)} № ${esc(d.number)}</strong><p>${esc(d.buyer)} · ${esc(d.date)} · ${draftReadiness(d)}</p></div><button class="button" data-edit="${i}">Открыть</button><button class="button" data-revise="${i}">Изменить</button><button class="button" data-html="${i}">↓ Документ</button></div>`).join('');}
function draftText(d){let s=`ЧЕРНОВИК — НЕ ОТПРАВЛЕН\n${d.type} № ${d.number} от ${d.date}\n\nОт: ${d.seller}\nКому: ${d.buyer}\nОснование: ${d.source}\n\n`;if(d.type==='Счёт'){const b=Number(d.qty)*Number(d.price),tax=b*Number(d.vat)/100;s+=`${d.item}\nКоличество: ${d.qty}\nЦена без НДС: ${cash(Number(d.price))} ₽\nСумма без НДС: ${cash(b)} ₽\nНДС (${d.vat}%): ${cash(tax)} ₽\nИТОГО: ${cash(b+tax)} ₽\n\nРеквизиты:\n${d.details}`;}else s+=d.body;return s+`\n\nПримечания:\n${d.notes||'—'}`;}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.mail!==undefined){selectedMail=Number(t.dataset.mail);renderMail();}if(t.dataset.compose)openCompose(t.dataset.compose);if(t.hasAttribute('data-close-compose'))compose.close();if(t.dataset.download!==undefined){const d=drafts[Number(t.dataset.download)],url=URL.createObjectURL(new Blob(['\uFEFF'+draftText(d)],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`Черновик-${d.type}-${d.number.replace(/[^\p{L}\p{N}-]/gu,'_')}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(t.dataset.edit!==undefined){compose.innerHTML=`<button class="close" data-close-compose aria-label="Закрыть">×</button><h2>Просмотр черновика</h2>${reviewPanel(Number(t.dataset.edit))}<pre class="draft-preview">${esc(draftText(drafts[Number(t.dataset.edit)]))}</pre><div class="preview-actions"><button class="button primary" data-revise="${t.dataset.edit}">Редактировать</button><button class="button" data-html="${t.dataset.edit}">↓ Версия для печати</button><button class="button" data-download="${t.dataset.edit}">↓ TXT</button><button class="button" data-copy-draft="${t.dataset.edit}">Дублировать</button></div>`;compose.showModal();}});
document.querySelector('#connection-info').onclick=()=>{compose.innerHTML='<button class="close" data-close-compose aria-label="Закрыть">×</button><span class="tag">ПОДКЛЮЧЕНИЕ НЕ НАСТРОЕНО</span><h2>Подключение рабочей почты</h2><p>Сообщите в чате, какой сервис использует отдел: Microsoft 365, Gmail, Яндекс или другой. Затем можно настроить подключение с разрешения владельца ящика.</p><p>Пароль от почты здесь не нужен. До подключения вы можете вставлять текст писем и готовить черновики вручную.</p><button class="button primary" data-close-compose>Понятно</button>';compose.showModal();};
document.querySelector('#paste-mail').onclick=()=>{compose.innerHTML=`<button class="close" data-close-compose aria-label="Закрыть">×</button><h2>Добавить текст письма</h2><p>Письмо останется только в текущей вкладке.</p><form id="paste-form">${field('Тема','subject','','required')}${field('Отправитель / организация','from','','required')}<label>Текст письма<textarea name="body" rows="7" required></textarea></label><label>Что подготовить<select name="kind"><option>Ответ</option><option>Счёт</option><option>Заявка</option></select></label><button type="submit" class="button primary">Добавить в очередь</button></form>`;compose.showModal();document.querySelector('#paste-form').onsubmit=e=>{e.preventDefault();const m=Object.fromEntries(new FormData(e.target));mails.push({...m,time:'Сейчас',task:'Проверьте письмо и заполните выбранный шаблон.',customer:m.from,item:'',qty:1});selectedMail=mails.length-1;renderMail();compose.close();};};renderMail();
